// Analyze Langfuse traces for performance anomalies
const response = $input.item.json;
let traces = [];

try {
  const result = response?.result?.content?.[0]?.text;
  if (result) traces = JSON.parse(result);
} catch (e) {
  // If parsing fails, continue with empty traces
}

const now = new Date();
const oneDayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);

// Performance metrics
let totalLatency = 0;
let totalCost = 0;
let traceCount = traces.length;
let highLatencyTraces = [];
let highCostTraces = [];
let lowScoreTraces = [];
let errorTraces = [];

const LATENCY_THRESHOLD_MS = 10000; // 10s
const COST_THRESHOLD = 0.50; // $0.50 per trace
const SCORE_THRESHOLD = 0.5; // below 50%

for (const trace of traces) {
  const latency = trace.latency || trace.duration || 0;
  const cost = trace.totalCost || trace.cost || 0;
  const score = trace.scores?.length > 0 
    ? trace.scores.reduce((a, s) => a + (s.value || 0), 0) / trace.scores.length 
    : null;

  totalLatency += latency;
  totalCost += cost;

  if (latency > LATENCY_THRESHOLD_MS) {
    highLatencyTraces.push({ id: trace.id, name: trace.name, latency, timestamp: trace.timestamp });
  }
  if (cost > COST_THRESHOLD) {
    highCostTraces.push({ id: trace.id, name: trace.name, cost, timestamp: trace.timestamp });
  }
  if (score !== null && score < SCORE_THRESHOLD) {
    lowScoreTraces.push({ id: trace.id, name: trace.name, score, timestamp: trace.timestamp });
  }
  if (trace.status === 'ERROR' || trace.statusMessage) {
    errorTraces.push({ id: trace.id, name: trace.name, error: trace.statusMessage, timestamp: trace.timestamp });
  }
}

const avgLatency = traceCount > 0 ? Math.round(totalLatency / traceCount) : 0;
const anomalyCount = highLatencyTraces.length + highCostTraces.length + lowScoreTraces.length + errorTraces.length;

// Determine severity
let severity = 'low';
if (errorTraces.length >= 5 || highLatencyTraces.length >= 10) severity = 'critical';
else if (errorTraces.length >= 2 || highLatencyTraces.length >= 5 || highCostTraces.length >= 3) severity = 'high';
else if (anomalyCount >= 3) severity = 'medium';

const report = {
  period: { from: oneDayAgo.toISOString(), to: now.toISOString() },
  summary: {
    totalTraces: traceCount,
    avgLatencyMs: avgLatency,
    totalCost: Math.round(totalCost * 100) / 100,
    anomalyCount,
    severity
  },
  anomalies: {
    highLatency: { count: highLatencyTraces.length, threshold: LATENCY_THRESHOLD_MS + 'ms', items: highLatencyTraces.slice(0, 5) },
    highCost: { count: highCostTraces.length, threshold: '$' + COST_THRESHOLD, items: highCostTraces.slice(0, 5) },
    lowScore: { count: lowScoreTraces.length, threshold: (SCORE_THRESHOLD * 100) + '%', items: lowScoreTraces.slice(0, 5) },
    errors: { count: errorTraces.length, items: errorTraces.slice(0, 5) }
  },
  hasAnomalies: anomalyCount > 0
};

return [{ json: report }];
